/// The OpenRocket commit the pins come from.
inline constexpr std::string_view kLugPanelPinsCommit = "5f164fd0e05d6e188857b0185601293b7a6e9eaf";

/// What the probe saw of one design: its sections, each a header line ("== panel | <index> |
/// <class>",
/// "== edit | <index> | <property> <value>", "== multi | <index> | <other index> | <class>", "==
/// multi edit | <property> <value>") and the lines that follow it, sorted (see
/// lug_panel_golden_tests.cpp).
struct LugPanelPin
{
    /// "example" (a file of data/examples), "testrocket" (a TestRockets maker) or "built" (a
    /// design of the probe, built in lug_panel_golden_tests.cpp).
    std::string_view source;
    std::string_view design;
    /// The design as a test name: letters and digits.
    std::string_view                  testName;
    std::span<const std::string_view> lines;
};

/// What GoogleTest prints for the design of a test that failed.
// NOLINTNEXTLINE(readability-identifier-naming): the name GoogleTest looks for
inline void PrintTo(const LugPanelPin& pin, std::ostream* out)
{
    *out << pin.source << ' ' << pin.design;
}

